package com.marsland.app;
import android.app.Activity; import android.os.Bundle; import android.webkit.WebView; import android.webkit.WebViewClient; import android.webkit.WebChromeClient; import android.webkit.WebSettings; import android.graphics.Color;
public class MainActivity extends Activity { private WebView web; private static final String URL="https://tordtaris.github.io/mars-land-explorer/"; @Override public void onCreate(Bundle b){super.onCreate(b);getWindow().setStatusBarColor(Color.rgb(5,10,19));getWindow().setNavigationBarColor(Color.rgb(5,10,19));web=new WebView(this);web.setBackgroundColor(Color.rgb(3,8,18));WebSettings s=web.getSettings();s.setJavaScriptEnabled(true);s.setCacheMode(WebSettings.LOAD_NO_CACHE);s.setDomStorageEnabled(true);s.setDatabaseEnabled(true);s.setLoadWithOverviewMode(true);s.setUseWideViewPort(true);s.setSupportZoom(false);web.setWebViewClient(new WebViewClient());web.setWebChromeClient(new WebChromeClient());setContentView(web);if(b==null)web.loadUrl(URL);else web.restoreState(b);}@Override protected void onSaveInstanceState(Bundle b){super.onSaveInstanceState(b);web.saveState(b);}@Override public void onBackPressed(){if(web!=null&&web.canGoBack())web.goBack();else super.onBackPressed();}}
